import os,json,hashlib;from pathlib import Path
assert os.geteuid()==10001
result={}
for location in ('/repo','/graphs'):
 root=Path(location);files={}
 for p in [root,*sorted(root.rglob('*'))]:
  s=p.stat(); row={'sha256':hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None,'size':s.st_size,'mode':s.st_mode,'mtime_ns':s.st_mtime_ns,'uid':s.st_uid,'gid':s.st_gid}
  files[str(p.relative_to(root))]=row
 result[location]=files
print(json.dumps(result,sort_keys=True))

